python
def resetTalliesPeakTicket(readings, k):
    a=readings
    out=[]
    total=0
    for x in a:
        total=0 if x==0 else total+x
        out.append(total)
    return max(out,default=0)


java
class Solution {
  public int resetTalliesPeakTicket(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int total=0;for(int x:a){total=x==0?0:total+x;out.add(total);}}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.max(answer,x);return answer;
  }
}
